import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import '../../../../core/theme/app_colors.dart';
import '../../../../core/theme/app_text_styles.dart';

/// Shows a password generated by the server. It is displayed only here, once,
/// so the administrator has to copy it or pass it on before closing.
Future<void> showTemporaryPasswordDialog(
  BuildContext context, {
  required String title,
  required String login,
  required String password,
}) {
  return showDialog<void>(
    context: context,
    barrierDismissible: false,
    builder: (_) => _TemporaryPasswordDialog(title: title, login: login, password: password),
  );
}

class _TemporaryPasswordDialog extends StatefulWidget {
  final String title;
  final String login;
  final String password;

  const _TemporaryPasswordDialog({required this.title, required this.login, required this.password});

  @override
  State<_TemporaryPasswordDialog> createState() => _TemporaryPasswordDialogState();
}

class _TemporaryPasswordDialogState extends State<_TemporaryPasswordDialog> {
  bool _copied = false;

  Future<void> _copy() async {
    await Clipboard.setData(ClipboardData(text: widget.password));
    if (mounted) setState(() => _copied = true);
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      title: Text(widget.title),
      content: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Передайте сотруднику данные для входа. Пароль показывается только один раз — после закрытия окна посмотреть его будет нельзя.',
            style: AppTextStyles.bodyMedium.copyWith(color: AppColors.textSecondary, height: 1.35),
          ),
          const SizedBox(height: 14),
          Text('Логин', style: AppTextStyles.caption),
          const SizedBox(height: 2),
          SelectableText(
            widget.login,
            style: TextStyle(fontWeight: FontWeight.w600, fontSize: 14, color: AppColors.textPrimary),
          ),
          const SizedBox(height: 12),
          Text('Временный пароль', style: AppTextStyles.caption),
          const SizedBox(height: 4),
          Container(
            padding: const EdgeInsets.only(left: 14, right: 4, top: 4, bottom: 4),
            decoration: BoxDecoration(
              color: AppColors.primaryBlue.withOpacity(0.08),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: AppColors.primaryBlue.withOpacity(0.3)),
            ),
            child: Row(
              children: [
                Expanded(
                  child: SelectableText(
                    widget.password,
                    style: TextStyle(
                      fontSize: 18,
                      fontWeight: FontWeight.bold,
                      letterSpacing: 1.2,
                      fontFamily: 'monospace',
                      color: AppColors.textPrimary,
                    ),
                  ),
                ),
                IconButton(
                  tooltip: 'Скопировать',
                  icon: Icon(
                    _copied ? Icons.check_rounded : Icons.copy_rounded,
                    color: _copied ? AppColors.success : AppColors.primaryBlue,
                    size: 20,
                  ),
                  onPressed: _copy,
                ),
              ],
            ),
          ),
          if (_copied) ...[
            const SizedBox(height: 6),
            const Text('Пароль скопирован', style: TextStyle(color: AppColors.success, fontSize: 12)),
          ],
          const SizedBox(height: 10),
          Text(
            'После входа сотрудник может сменить пароль в разделе «Настройки».',
            style: AppTextStyles.caption.copyWith(color: AppColors.textSecondary),
          ),
        ],
      ),
      actions: [
        ElevatedButton(
          onPressed: () => Navigator.pop(context),
          style: ElevatedButton.styleFrom(
            backgroundColor: AppColors.primaryBlue,
            foregroundColor: Colors.white,
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
          ),
          child: const Text('Готово'),
        ),
      ],
    );
  }
}
